const conversations = $input.all();

if (conversations.length === 0) {
  return [{ json: { message: 'No conversations to summarize' } }];
}

return conversations.map(item => ({
  json: {
    conversation_id: item.json.conversation_id,
    tenant_id: item.json.tenant_id,
    platform: item.json.platform,
    contact_id: item.json.contact_id,
    message_count: item.json.message_count,
    conversation_text: item.json.conversation_text,
    last_message_at: item.json.last_message_at
  }
}));

const summary = $('Generate Summary').first().json.content;
const conversationData = $('Format Conversation').first().json;
const embedding = $('Embed Summary').first().json.embedding;

// Simple keyword extraction
const commonWords = ['the', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'is', 'are', 'was', 'were', 'be', 'been', 'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'could', 'should', 'may', 'might', 'can', 'a', 'an', 'this', 'that', 'these', 'those'];

const words = summary.toLowerCase().match(/\b\w+\b/g) || [];
const keyWords = words.filter(word => word.length > 3 && !commonWords.includes(word));

// Count word frequency
const wordCount = {};
keyWords.forEach(word => {
  wordCount[word] = (wordCount[word] || 0) + 1;
});

// Get top keywords
const topKeywords = Object.entries(wordCount)
  .sort(([,a], [,b]) => b - a)
  .slice(0, 10)
  .map(([word]) => word);

// Simple sentiment analysis
const positiveWords = ['good', 'great', 'excellent', 'happy', 'satisfied', 'pleased', 'thank', 'thanks'];
const negativeWords = ['bad', 'terrible', 'awful', 'angry', 'frustrated', 'disappointed', 'problem', 'issue', 'complaint'];

const positiveCount = words.filter(word => positiveWords.includes(word)).length;
const negativeCount = words.filter(word => negativeWords.includes(word)).length;

let sentiment = 'neutral';
if (positiveCount > negativeCount) sentiment = 'positive';
else if (negativeCount > positiveCount) sentiment = 'negative';

const vectorString = `[${embedding.join(',')}]`;

return {
  json: {
    conversation_id: conversationData.conversation_id,
    tenant_id: conversationData.tenant_id,
    summary: summary,
    summary_embedding: vectorString,
    key_topics: topKeywords,
    sentiment: sentiment,
    message_count: conversationData.message_count,
    platform: conversationData.platform
  }
};
